from pathlib import Path
import re

root = Path(__file__).resolve().parent.parent
s = (root / '_WORK/AUTHOR_DRAFT.md').read_text(encoding='utf-8-sig')

# Move only Markdown destinations. Neighbouring research keeps one parent.
def move_link(m):
    dest = m.group(1)
    if re.match(r'\.\./(?:RAW_FACTS|SOURCES|OPEN_QUESTIONS)\.md(?:#|$)', dest):
        dest = dest[3:]
    elif dest == 'COLLECTOR_HANDOFF.md':
        dest = '_WORK/COLLECTOR_HANDOFF.md'
    elif dest.startswith('../../'):
        dest = dest[3:]
    return '](' + dest + ')'
s = re.sub(r'\]\(([^)]+)\)', move_link, s)

# Revise complete paragraphs where a literal substitution would obscure meaning.
paragraphs = {
'Сильнейшая подготовленная стратегия': 'Для нашей команды приоритет — как можно раньше завершить настоящий запуск на LinQ, связать его с обязательным результатом кейса и сохранить доказательства до расширения функций. Работа пятерых строится вокруг одной пригодной сборки и точных передач между владельцами. Отдельное время нужно выделить качеству модели, действию пользователя, запуску с другой машины, формальной сдаче и защите: у каждого участка свои условия готовности.',
'Другой существенный результат': 'Исследование также позволило выделить минимальный пакет доказательств первого полезного запуска. Он связывает разрешённый вход, точную версию модели, завершение и выход с доверенной привязкой к LinQ либо свидетельством, которое принимает постановщик. Интеграцию управляемого сервиса можно продолжать, даже если интерфейс не выдаёт версию прошивки или байты внутреннего скомпилированного файла. При этом надпись `LinQ` в интерфейсе не доказывает отсутствующую связь с устройством. Предложенный минимум — наша инженерная рекомендация; его достаточность для зачёта должен подтвердить постановщик. [F060](RAW_FACTS.md#f060), [F065–F066](RAW_FACTS.md#f065), [E001](OPEN_QUESTIONS.md#e001), [Q008](OPEN_QUESTIONS.md#q008).',
'Качество также следует': 'Качество следует оценивать на том уровне, для которого есть данные. Для полноценных событийных метрик нужна соответствующая независимая разметка. Без неё можно показать диагностические результаты, нагрузку канала или узкую оценку всех доставленных тревог, явно сохранив неизвестные исходы. Несколько успешных примеров не дают процента точности. Если полный кейс потребует официальную метрику, собственная удобная цифра её не заменит. [F076–F077](RAW_FACTS.md#f076), [Q012](OPEN_QUESTIONS.md#q012).',
'Ниже официальное правило': 'В отчёте различаются официальное правило, сообщение участника или производителя, статическое чтение кода и наше предложение. Ссылки F ведут к подробным основаниям, S — к происхождению источника, Q — к незакрытому вопросу. Рядом с рекомендацией указаны её основания и условия применения. Это подготовительное исследование: готовая презентация, сдаваемый тизер, речь, демо-сценарий и приложение здесь не создаются.',
'Следовательно, первым адресным': 'Первый запрос организатору — действующая оценочная форма технологического LinQ-кейса с весами, описаниями уровней, порядком сведения оценок и вкладом чек-поинтов. Пока ответа нет, вклад CP остаётся неизвестным. Матрица семи критериев помогает проверить полноту работы. Новые функции выбирают по обязательности, полезности и возможности довести их до проверки; предполагаемый «ещё один балл» не оправдывает риск потерять работающее ядро.',
'Возможное отличие нашей команды': 'Возможное отличие команды стоит искать в узкой проверяемой функции выданного кейса: прослеживаемой цепи «точный вход → версия модели → принятое свидетельство LinQ → событие → фактическая доставка или разбор → отдельное действие», видимости неизвестных исходов и отказов, корректной обработке позднего результата. Это гипотеза для реализации и сравнения. Наличие такой функции у конкурентов пока не установлено. Сравнивать следует конкретную редакцию продукта (SKU/build) по одинаковому протоколу, если он доступен. Если отличие доказать не удалось, итог — «новизна не установлена» с объяснением собственного интеграционного вклада. Чужая документация не доказывает превосходство нашего качества или цены и не позволяет приписать всему Intenseye отсутствие прослеживаемости результатов. [F073](RAW_FACTS.md#f073), [Q027](OPEN_QUESTIONS.md#q027).',
'Минимальный следующий пилотный вход': 'Для следующей пилотной проверки нужны один утверждённый процесс, правило и ответственное лицо; разрешённый исходный материал с известным происхождением; действительные условия доступа к вычислительной платформе; ожидаемый результат и признак недостаточности данных; разрешённый канал доставки или явно внутренний тестовый получатель. Этот перечень показывает необходимые входы проверки. Промышленную готовность ещё предстоит установить, а обязательные требования кейса остаются в силе. Сравнение технологий полезно, когда меняет выбор процесса или его ограничения; общая фраза о важности безопасности не раскрывает потребности аудитории.',
'Например, сочетание supplied scorer': 'Например, если одновременно выданы официальный расчёт метрики, длинный обязательный список, сервис заданий, реальное видео и обязательный API, первый маршрут — совместимая базовая модель и точный формат API, параллельно с измерением полного цикла задания. Выбор одной каски как удобного MVP не закрывает остальные обязательности. Если нет ни доступа, ни видео целевого объекта, результат первых двух часов — список недостающих входов, прав, владельцев и следующих действий. Эффектный показ на заранее придуманных условиях этих пробелов не закрывает.',
'Особенно легко перегрузить P5.': 'Особенно легко перегрузить P5: чек-поинт, разметка спорных случаев, приёмка сборки и загрузка материалов требуют его отдельного внимания. P2 готовит разметку и журнал результатов; P5 получает отдельное окно их проверки. P3 выпускает сборку, P4 собирает материалы, P5 принимает их вне CP, затем вместе с другим бодрствующим участником проверяет сдачу. Если второго независимого разбора нет, нужно уменьшить корпус и силу утверждения, оставить неизвестный исход или диагностический статус. Набор, на котором P2 только что выбирал модель, нельзя назвать независимым holdout, а собственное повторное чтение — независимой оценкой. [F079–F081](RAW_FACTS.md#f079).',
'Небольшой переход возвращается': 'Небольшое изменение возвращают в общую рабочую ветку после короткой проверки поведения. Git обнаруживает текстовый конфликт, но не перепутанный порядок классов или потерянный ID события. Изменение схемы, предобработки или классов согласуют со всеми потребителями и обновляют тестовые примеры. Для больших весов и данных фиксируют место хранения, описание состава и хеш; перезапись не должна проходить незаметно. Улучшенный локальный результат экспериментальной ветки ещё нужно провести через общую проверку и интеграцию.',
'Заморозки имеют разные предметы.': 'Для разных изменений нужны отдельные рубежи. Приём новых идей заканчивается раньше; модельному кандидату назначают последний полезный срок с учётом всех следующих стадий; интерфейсы фиксируют до последней интеграции; загрузке оставляют собственный резерв. При задержке доступа сокращают необязательные расширения, сохраняя обязательный результат, возможности сна и проверку приёма материалов.',
'После первого полного среза P1/P2': 'После первого полного среза P1/P2 готовят один пригодный модельный пакет и сравнивают доступные стадии исполнения. P3 проверяет ошибки и восстановление, P4 и P5 создают черновики CP2. P2 готовит диагностическую эталонную разметку; P5 проверяет её в отдельное время. После CP2 допускается лишь кандидат, которому хватает времени пройти весь оставшийся путь до D_useful. К CP3 P3 выпускает сборку, P1 подтверждает происхождение и исполнение её точной версии, P4 пакует материалы. P5 ведёт встречу, затем отдельно принимает сборку. Утром P3/P4 проверяют старт и ссылки, P5 загружает материалы и получает подтверждение приёма со вторым бодрствующим проверяющим.',
'К этому моменту без ложного target claim': 'К этому моменту уже должны быть матрица обязательностей, разрешённые входы, базовое решение с указанием фактической среды, согласованные тестовые примеры, UI или требуемый интерфейс, черновики CP2, упаковка и документированное препятствие доступу. Исполнение на LinQ при этом не заявляется. P1 ведёт один точный статус доступа; остальные продолжают независимую работу. Рубеж раннего предупреждения — 23 октября в 15:00; предметная эскалация — на CP1, повторная — на CP2, если обязательного запуска всё ещё нет. Это внутренние рубежи, не сроки дисквалификации.',
'Ниже собственные подготовленные вопросы': 'Ниже — подготовленные вопросы команды, которые ещё не задавались. Связанные пункты стоит объединять: документацию подходящей версии, входы/выходы и лимиты лучше запросить одним пакетом. Устный ответ кратко подтверждают в разрешённом канале, фиксируя полномочия ответившего и версию кейса. [Банк неизвестного](OPEN_QUESTIONS.md).',
'Есть два различных звена.': 'Доказательство работы на LinQ состоит из двух звеньев. Сначала нужно связать исходную модель, экспорт и конфигурацию с загруженной версией и допустимым составом исполнения. Затем — связать конкретный вход или запрос с завершением этой версии на установленном устройстве и полученным выходом. Эту привязку далее называем mapping, а принимаемое постановщиком свидетельство конкретного запуска — witness. Хеш связывает байты, но сам по себе не доказывает качество, время создания, размещение вычислений или факт запуска. Корректный выход возможен на CPU, а общая загрузка устройства может относиться к соседним заданиям. [F065](RAW_FACTS.md#f065).',
'В managed service stable server revision': 'Управляемый сервис может предоставлять только устойчивую серверную версию и документированные условия исполнения; в таком режиме это может быть самым сильным доступным свидетельством. Принять эту границу доверия должен постановщик 2026. Отсутствие внутренних скомпилированных байтов не блокирует интеграцию само по себе. Если нет никакой привязки к устройству, исполнение на LinQ остаётся неустановленным. По возможности сохраняют версии компилятора и runtime, ID устройства, отчёт компиляции, хеш загруженного артефакта, профиль исполнения, аппаратные таймеры и сведения об отсутствии переключения на другую платформу. Это полезные инженерные сведения; отдельными требованиями конкурса они становятся только по его правилам. [Q008–Q011](OPEN_QUESTIONS.md#q008), [Q023](OPEN_QUESTIONS.md#q023).',
'Стартовая карточка одного результата': 'Для одного результата записывают цель и единицу оценки, происхождение и объём данных, независимость набора или его диагностический статус, определение успеха и порог, числитель, знаменатель, неизвестные исходы, ошибки и область применимости. Входы, модель, конфигурацию и процедуру расчёта фиксируют до измерения. Соседние кадры одного ролика не образуют независимый тест на новых камерах. Все ожидаемые входы учитывают как успешные, ошибочные/потерянные либо незавершённые; повторные попытки связывают с исходными запросами. При нулевом знаменателе выводят NA. Если обязательная официальная процедура расчёта не получена, это незакрытое требование; дополнительную метрику нельзя выдать за официальную. [F076–F077](RAW_FACTS.md#f076), [E003](OPEN_QUESTIONS.md#e003).',
'Следующая таблица задаёт допустимость': 'Таблица показывает, какие будущие утверждения допустимы при разных входах. Ground truth (GT) — эталонная разметка, с которой сопоставляют результат. Своих GT и журналов работы у команды пока нет; приведённые ниже цифры не измерены. Для ближайшего решения следует выбрать один показатель или результат проверки, для которого хватает оснований, и обозначить следующий необходимый вход. [F076](RAW_FACTS.md#f076).',
'Полный разбор всех доставленных тревог': 'Полный разбор всех доставленных тревог позволяет узко оценить семантическую нагрузку ложных сообщений на известных часах исходного видео, даже без разметки всей тишины. В таблице I — фиксированная совокупность исходного материала, H — её камера-часы, F — число ложных доставленных записей, U — число неизвестных исходов, C — момент закрытия разбора. Поэтому F/H описывает именно эту нагрузку; диапазон [F/H, (F+U)/H] допустим при независимо зафиксированных эталонных оценках. Для recall нужен независимый поиск пропущенных событий. Необработанные интервалы без тревог нельзя автоматически назвать нормальными. Часы исходного видео (source camera-hours) и фактические часы нагрузки канала или оператора (wall-hours) имеют разный смысл. Малое F/H во время отказа системы не доказывает улучшение модели: рядом нужны покрытие исходного материала, ошибки и незавершённые запросы. [F076](RAW_FACTS.md#f076).',
'Semantic correctness, своевременность': 'Семантическую правильность, своевременность, намеренные напоминания и избыточные/дублирующие записи размечают отдельно. Истинное опоздавшее событие сохраняет семантическую правильность, а истинная лишняя запись всё равно создаёт нагрузку. Указывают момент закрытия C, оставшиеся неизвестные исходы и незавершённые сопоставления. Разбор выбранных тревог не находит событий, которых система не выдала. Продуктовое название Accuracy API этого не меняет: прочитанная схема Intenseye содержит поля выборки тревог, но не независимый полный список пропусков. Формула `accuracyRate` из примера не восстановлена и в наш отчёт не переносится. [Accuracy API](https://docs.intenseye.com/docs/v2_accuracy/index.html); [F071](RAW_FACTS.md#f071).',
'На первом малом evidence package': 'Первый небольшой пакет может состоять из одного описания состава и журнала связей: разрешённый вход, модель и конфигурация, завершённый запуск с доверенной привязкой, выход, таблица доступного результата, исходный материал, один отказ или неизвестный исход и граница проверки. Полезные поля соседнего evaluation можно хранить вместе. До заморозки P2 передаёт тип, полноту и происхождение GT, P3 — доступность журналов завершения и доставки, P1 — точную версию и привязку к устройству. Если нужный вход не получить до оставленного времени упаковки, расчёт неподтверждённого процента прекращают: показывают диагностические количества или NA и называют следующий вход. Отсутствие обязательной метрики остаётся незавершённым требованием. [F077](RAW_FACTS.md#f077).',
'Model throughput, device latency': 'Пропускная способность модели, задержка на устройстве, полное время запроса от клиента (RTT) и задержка события до пользователя описывают разные границы. При пакетах, конвейере и параллельных запросах FPS нельзя перевести в задержку через `1/FPS`. Вычитание ping из RTT тоже не даёт времени инференса на устройстве: полезная нагрузка, очередь, сериализация и серверная обработка отличаются от условий ping. Отправленные запросы учитывают отдельно от завершённых. [F061–F062](RAW_FACTS.md#f061), [F109](RAW_FACTS.md#f109).',
'Пока сервис и режим комнаты': 'Сервис и режим комнаты 2026 пока неизвестны. Партнёрская ссылка МТС на текущем сайте и его роль в 2025 — зацепки для уточнения. Они не устанавливают продукт (Встречи/Вебинары), фактическую комнату, роль докладчика, права на файлы/экран/звук и порядок замены презентующего. Внутренне назначенный резерв ещё должен получить разрешение организатора. После выдачи ссылки определяют режим и роль, читают соответствующую справку и проверяют показ с отдельным зрителем. [F097](RAW_FACTS.md#f097), [Q015](OPEN_QUESTIONS.md#q015).',
'Принцип демонстрации —': 'В центре демонстрации — одна короткая наблюдаемая связь между входом, решением и полезным действием. Конкретный результат выбирают с постановщиком: это может быть не только немедленная тревога в браузере. Зрителю нужны источник и момент, результат со статусом, доступное доказательство, понятное действие и состояние отказа. Длинная экскурсия по кнопкам мешает проверить основную связь. Одиночный удачный клип сопровождают результатом проверки или прямым указанием, что статистической оценки пока нет.',
'Семь одинаковых отрезков': 'Распределять пять минут поровну между семью критериями нет опубликованного основания. Одно короткое действие может объяснить прототип, основную проблему и UX/UI. Матрица критериев проверяет полноту: у каждого есть факт и ссылка на его основание. Последовательность рассказа строят по тому, что зритель должен увидеть и понять. Один тезис, проверяемое основание и существенная граница дают достаточную единицу объяснения. [F104–F105](RAW_FACTS.md#f104).',
'**Observed Q&A = 0.**': '**Лично просмотренных вопросов жюри — ноль (observed Q&A = 0).** Две темы со статусом reported взяты из одного первичного рассказа «Чёрной уточки» о РЖД-2024. Остальные двенадцать имеют статус anticipated: это наши предположения из анонса, критериев и рисков. Банк не показывает частоту вопросов Моспрома и предпочтения конкретных судей. Найденная отметка времени НКБТех сохраняет статус ссылки до фактического просмотра. [F041](RAW_FACTS.md#f041), [F058](RAW_FACTS.md#f058), [F106](RAW_FACTS.md#f106), [банк QA](OPEN_QUESTIONS.md#qa001).',
'Первой идёт короткая связанная': 'Первой идёт короткая связанная проверка E001 + E002 + E003: пройти доступный штатный пример исполнения, сохранить его связи с входом и выходом, проверить положительный/пустой/ошибочный случаи на ближайшем стыке и выбрать один результат оценки, для которого хватает данных. Затем E004 переводит наблюдённые длительности в календарь; E006 и E007 защищают переносимость, показ и сдачу. Остальные проверки добавляют по требованиям и доступам. [F077](RAW_FACTS.md#f077), [реестр процедур](OPEN_QUESTIONS.md#e001).',
'Приоритет после первого короткого пакета': 'После первого короткого пакета приоритет зависит от результата. Если исполнение на платформе не работает, нужно получить поддерживаемый путь и свидетельство запуска. Если путь есть, но смысловой результат неверен, локализуют расхождение: объект, связь с человеком, правило или доставка. Недостаток прав решают с правообладателем. После приёмки обязательной цепи допускается одно ограниченное улучшение, которое проходит все следующие стадии; затем время сохраняют для чистого выпуска и проверки зрителем.',
'Для старта команды наиболее полезен': 'На старте команда получает действующую оценочную форму и полный перечень обязательностей, устанавливает выданный путь исполнения и принимаемое свидетельство, выбирает разрешённый вход и один обоснованный показатель, назначает владельцев и последний полезный срок модельного кандидата. Ближайший результат — небольшой связанный пакет доказательств, который другой участник способен открыть и повторить. Расширять объём можно при сохранении времени на обязательные материалы, отдых, сдачу, защиту и награждение.',
}
